// Один запрос к LLM на все выбросы: так модель видит их вместе и не делает дублей.
const outs = $('Scout (Django)').first().json.outliers;
const posts = outs.map((o, i) =>
  `#${i}. ${o.views} просмотров, ${o.reactions} реакций, ×${o.score} к медиане канала
${o.text}`
).join('

---

');
const prompt = `Уже были (не повторять):
${$json.titles || '—'}

Посты:

${posts}`;
return [{ json: { prompt } }];

